// Loading models (the .b3d files of Blitz3D), and animating them.
//
// A model is a tree of nodes. Each node is an entity, which can have a mesh. Nodes have keys that say where they are,
// how big they are and how they are turned at certain frames, and nodes can be bones: they pull the vertices of the
// mesh along, each by a weight. Animating moves the bones, and then every vertex is put where its bones say.

#include <math.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#include "scene.hpp"

extern "C" {
void    bb_runtime_error(const char* message);
int32_t bb_load_texture(const char* file, int32_t flags);
void    bb_name_entity(int32_t handle, const char* name);
}

namespace bb {
	struct key3 {
		float frame;
		float v[3];
	};

	struct key4 {
		float frame;
		float q[4]; // w, x, y, z
	};

	// What a node does over time, and where it started.
	struct anim_node {
		int   parent = -1; // Index of another node, which always comes before this one.
		int   handle = 0;  // The entity of this node.
		bool  has_mesh = false;
		bool  is_bone  = false;
		float pos[3]   = { 0, 0, 0 };
		float scale[3] = { 1, 1, 1 };
		float rot[4]   = { 1, 0, 0, 0 };
		buffer<key3> pos_keys, scale_keys;
		buffer<key4> rot_keys;
		float bind_model[16];    // Where the node is in the model, when nothing is animated.
		float inverse_bind[16];
	};

	struct seq_range {
		float first, last;
	};

	// The animation of a model, kept by its top entity.
	struct animation {
		float             frames = 1, fps = 60;
		buffer<anim_node*> nodes;
		buffer<seq_range>  sequences; // 0 is all of the frames.
		int               mode      = 0; // 0 = not playing, 1 = loop, 2 = ping pong, 3 = once
		float             speed     = 1;
		int               sequence  = 0;
		float             time      = 0;
		float             direction = 1;
	};

	// For each vertex of a surface: where it was and by which bones it is moved.
	struct skin_data {
		int               mesh_node = 0;
		buffer<float>     bind_position; // 3 per vertex
		buffer<float>     bind_normal;   // 3 per vertex
		buffer<uint32_t>  start;         // Where the weights of a vertex start, one more than there are vertices.
		buffer<int>       bone;          // Node index
		buffer<float>     weight;
	};

	void destroy_skin(skin_data* s)
	{
		s->bind_position.release();
		s->bind_normal.release();
		s->start.release();
		s->bone.release();
		s->weight.release();
		delete s;
	}

	template<typename T>
	static void copy_buffer(buffer<T>& to, buffer<T> const& from)
	{
		to.data = nullptr;
		to.size = to.cap = 0;
		to.reserve(from.size);
		if (from.size) {
			memcpy(to.data, from.data, from.size * sizeof(T));
		}
		to.size = from.size;
	}

	skin_data* clone_skin(skin_data const& s)
	{
		skin_data* copy = new skin_data();
		copy->mesh_node = s.mesh_node;
		copy_buffer(copy->bind_position, s.bind_position);
		copy_buffer(copy->bind_normal, s.bind_normal);
		copy_buffer(copy->start, s.start);
		copy_buffer(copy->bone, s.bone);
		copy_buffer(copy->weight, s.weight);
		return copy;
	}

	static void destroy_node(anim_node* n)
	{
		n->pos_keys.release();
		n->scale_keys.release();
		n->rot_keys.release();
		delete n;
	}

	void destroy_animation(animation* a)
	{
		for (uint32_t i = 0; i < a->nodes.size; i++) {
			destroy_node(a->nodes[i]);
		}
		a->nodes.release();
		a->sequences.release();
		delete a;
	}

	animation* clone_animation(animation const& a, buffer<int> const& was, buffer<int> const& now)
	{
		animation* copy = new animation();
		copy->frames    = a.frames;
		copy->fps       = a.fps;
		copy->mode      = a.mode;
		copy->speed     = a.speed;
		copy->sequence  = a.sequence;
		copy->time      = a.time;
		copy->direction = a.direction;
		copy_buffer(copy->sequences, a.sequences);
		for (uint32_t i = 0; i < a.nodes.size; i++) {
			anim_node* from = a.nodes[i];
			anim_node* to   = new anim_node(*from);
			copy_buffer(to->pos_keys, from->pos_keys);
			copy_buffer(to->scale_keys, from->scale_keys);
			copy_buffer(to->rot_keys, from->rot_keys);
			for (uint32_t m = 0; m < was.size; m++) {
				if (was[m] == from->handle) {
					to->handle = now[m];
					break;
				}
			}
			copy->nodes.push(to);
		}
		return copy;
	}
} // namespace bb

namespace {
	using namespace bb;

	[[noreturn]] void fail(const char* what)
	{
		bb_runtime_error(what);
		exit(1);
	}

	////////////////////////////////////////////////////////////////////////////
	// Matrices and quaternions
	////////////////////////////////////////////////////////////////////////////
	// Matrix for a position, a scale and a quaternion (w, x, y, z).
	void compose(float* m, const float* pos, const float* scale, const float* q)
	{
		float w = q[0], x = q[1], y = q[2], z = q[3];
		float len = sqrtf(w * w + x * x + y * y + z * z);
		if (len > 1e-12f) {
			w /= len;
			x /= len;
			y /= len;
			z /= len;
		}
		float xx = x * x, yy = y * y, zz = z * z, xy = x * y, xz = x * z, yz = y * z, wx = w * x, wy = w * y, wz = w * z;
		float r[3][3] = {
			// The quaternions of the original turn the other way round than the usual ones.
			{ 1 - 2 * (yy + zz), 2 * (xy + wz), 2 * (xz - wy) },
			{ 2 * (xy - wz), 1 - 2 * (xx + zz), 2 * (yz + wx) },
			{ 2 * (xz + wy), 2 * (yz - wx), 1 - 2 * (xx + yy) },
		};
		memset(m, 0, sizeof(float) * 16);
		for (int col = 0; col < 3; col++) {
			for (int row = 0; row < 3; row++) {
				m[col * 4 + row] = r[row][col] * scale[col];
			}
		}
		m[12] = pos[0];
		m[13] = pos[1];
		m[14] = pos[2];
		m[15] = 1;
	}

	void transform_point(const float* m, const float* p, float* out)
	{
		for (int row = 0; row < 3; row++) {
			out[row] = m[0 + row] * p[0] + m[4 + row] * p[1] + m[8 + row] * p[2] + m[12 + row];
		}
	}

	void transform_direction(const float* m, const float* p, float* out)
	{
		for (int row = 0; row < 3; row++) {
			out[row] = m[0 + row] * p[0] + m[4 + row] * p[1] + m[8 + row] * p[2];
		}
	}

	////////////////////////////////////////////////////////////////////////////
	// Where a node is at a time
	////////////////////////////////////////////////////////////////////////////
	template<typename K>
	void find_keys(buffer<K> const& keys, float frame, uint32_t& before, uint32_t& after, float& blend)
	{
		if (frame <= keys[0].frame) {
			before = after = 0;
			blend          = 0;
			return;
		}
		for (uint32_t i = 1; i < keys.size; i++) {
			if (frame <= keys[i].frame) {
				before = i - 1;
				after  = i;
				float span = keys[i].frame - keys[i - 1].frame;
				blend      = span > 1e-6f ? (frame - keys[i - 1].frame) / span : 0;
				return;
			}
		}
		before = after = keys.size - 1;
		blend          = 0;
	}

	void sample_vector(buffer<key3> const& keys, float frame, float* out)
	{
		if (keys.size == 0) {
			return;
		}
		uint32_t a, b;
		float    t;
		find_keys(keys, frame, a, b, t);
		for (int i = 0; i < 3; i++) {
			out[i] = keys[a].v[i] + (keys[b].v[i] - keys[a].v[i]) * t;
		}
	}

	void sample_rotation(buffer<key4> const& keys, float frame, float* out)
	{
		if (keys.size == 0) {
			return;
		}
		uint32_t a, b;
		float    t;
		find_keys(keys, frame, a, b, t);
		float sign = 1;
		float d    = keys[a].q[0] * keys[b].q[0] + keys[a].q[1] * keys[b].q[1] + keys[a].q[2] * keys[b].q[2] + keys[a].q[3] * keys[b].q[3];
		if (d < 0) {
			sign = -1; // The short way around.
		}
		for (int i = 0; i < 4; i++) {
			out[i] = keys[a].q[i] + (keys[b].q[i] * sign - keys[a].q[i]) * t;
		}
	}

	// The pose of one node at a frame: position, scale and rotation.
	void node_pose(anim_node const& n, float frame, float* pos, float* scale, float* rot)
	{
		memcpy(pos, n.pos, sizeof(n.pos));
		memcpy(scale, n.scale, sizeof(n.scale));
		memcpy(rot, n.rot, sizeof(n.rot));
		sample_vector(n.pos_keys, frame, pos);
		sample_vector(n.scale_keys, frame, scale);
		sample_rotation(n.rot_keys, frame, rot);
	}

	// Puts everything in a model where it belongs at a frame, which includes moving the vertices of skinned meshes.
	void apply_pose(animation& a, float frame)
	{
		uint32_t count = a.nodes.size;
		float*   models = static_cast<float*>(malloc(size_t(count) * 16 * sizeof(float)));
		bool     any_bones = false;
		for (uint32_t i = 0; i < count; i++) {
			anim_node& n = *a.nodes[i];
			float      pos[3], scale[3], rot[4], local[16];
			node_pose(n, frame, pos, scale, rot);
			compose(local, pos, scale, rot);
			if (n.parent >= 0) {
				mat_multiply(models + i * 16, models + size_t(n.parent) * 16, local);
			} else {
				memcpy(models + i * 16, local, sizeof(local));
			}
			any_bones = any_bones || n.is_bone;

			// The first node is where the whole model is placed, which belongs to the program and not to the animation.
			if ((i > 0) && get_entity(n.handle)) {
				entity* e = get_entity(n.handle);
				memcpy(e->position, pos, sizeof(pos));
				memcpy(e->scale, scale, sizeof(scale));
				float rotation_matrix[16];
				float unit[3] = { 1, 1, 1 };
				compose(rotation_matrix, pos, unit, rot);
				euler_from_matrix(rotation_matrix, e->rotation);
			}
		}

		if (any_bones) {
			// Bone matrices: from the bind pose to now.
			float* skin = static_cast<float*>(malloc(size_t(count) * 16 * sizeof(float)));
			for (uint32_t i = 0; i < count; i++) {
				mat_multiply(skin + i * 16, models + i * 16, a.nodes[i]->inverse_bind);
			}
			for (uint32_t i = 0; i < count; i++) {
				anim_node& n = *a.nodes[i];
				entity*    e = n.has_mesh ? get_entity(n.handle) : nullptr;
				if (!e) {
					continue;
				}
				float pose_inverse[16];
				mat_affine_inverse(models + i * 16, pose_inverse);
				for (uint32_t s = 0; s < e->surfaces.size; s++) {
					surface*   surf = e->surfaces[s];
					skin_data* sk   = surf->skin;
					if (!sk) {
						continue;
					}
					const float* bind = a.nodes[sk->mesh_node]->bind_model;
					for (uint32_t v = 0; v < surf->vertices.size; v++) {
						float p[3], n3[3];
						transform_point(bind, &sk->bind_position[v * 3], p);
						transform_direction(bind, &sk->bind_normal[v * 3], n3);
						float moved[3] = { 0, 0, 0 }, moved_normal[3] = { 0, 0, 0 };
						float total = 0;
						for (uint32_t w = sk->start[v]; w < sk->start[v + 1]; w++) {
							const float* m = skin + size_t(sk->bone[w]) * 16;
							float        q[3], qn[3];
							transform_point(m, p, q);
							transform_direction(m, n3, qn);
							for (int k = 0; k < 3; k++) {
								moved[k] += q[k] * sk->weight[w];
								moved_normal[k] += qn[k] * sk->weight[w];
							}
							total += sk->weight[w];
						}
						if (total < 1e-6f) {
							memcpy(moved, p, sizeof(p));
							memcpy(moved_normal, n3, sizeof(n3));
						}
						float local[3], local_normal[3];
						transform_point(pose_inverse, moved, local);
						transform_direction(pose_inverse, moved_normal, local_normal);
						float length = sqrtf(local_normal[0] * local_normal[0] + local_normal[1] * local_normal[1] + local_normal[2] * local_normal[2]);
						if (length > 1e-9f) {
							local_normal[0] /= length;
							local_normal[1] /= length;
							local_normal[2] /= length;
						}
						vertex3d& vert = surf->vertices[v];
						vert.x = local[0];
						vert.y = local[1];
						vert.z = local[2];
						vert.nx = local_normal[0];
						vert.ny = local_normal[1];
						vert.nz = local_normal[2];
					}
					surf->dirty = true;
				}
			}
			free(skin);
		}
		free(models);
	}

	// The model that an entity is part of: the closest entity above that has an animation.
	animation* animation_of(int handle)
	{
		for (int h = handle; h; ) {
			entity* e = get_entity(h);
			if (!e) {
				return nullptr;
			}
			if (e->anim) {
				return e->anim;
			}
			h = e->parent;
		}
		return nullptr;
	}

	////////////////////////////////////////////////////////////////////////////
	// Reading .b3d files
	////////////////////////////////////////////////////////////////////////////
	struct reader {
		const uint8_t* data;
		size_t         size;
		size_t         pos;
		bool           failed;

		bool have(size_t count)
		{
			if (pos + count > size) {
				failed = true;
				return false;
			}
			return true;
		}

		int32_t read_int()
		{
			int32_t v = 0;
			if (have(4)) {
				memcpy(&v, data + pos, 4);
				pos += 4;
			}
			return v;
		}

		float read_float()
		{
			float v = 0;
			if (have(4)) {
				memcpy(&v, data + pos, 4);
				pos += 4;
			}
			return v;
		}

		// A string that ends with a zero byte.
		char* read_string()
		{
			size_t start = pos;
			while ((pos < size) && data[pos]) {
				pos++;
			}
			if (pos >= size) {
				failed = true;
				return nullptr;
			}
			size_t length = pos - start;
			char*  out    = static_cast<char*>(malloc(length + 1));
			memcpy(out, data + start, length);
			out[length] = 0;
			pos++;
			return out;
		}
	};

	struct tex_info {
		char* name  = nullptr;
		int   flags = 0;
		int   handle = -1; // Loaded when it is first needed, 0 if that failed.
	};

	struct brush_info {
		float color[4]  = { 1, 1, 1, 1 };
		float shininess = 0;
		int   blend = 1, fx = 0;
		int   texture = -1;
	};

	struct vertex_info {
		float pos[3] = { 0, 0, 0 };
		float normal[3] = { 0, 0, 0 };
		float color[4]  = { 1, 1, 1, 1 };
		float uv[2]     = { 0, 0 };
	};

	struct triangle_group {
		int              brush = -1;
		buffer<uint32_t> indices;
	};

	struct node_info {
		char*  name = nullptr;
		int    parent = -1;
		float  pos[3] = { 0, 0, 0 }, scale[3] = { 1, 1, 1 }, rot[4] = { 1, 0, 0, 0 };
		bool   has_mesh = false, has_normals = true, is_bone = false;
		int    mesh_brush = -1;
		buffer<vertex_info>    vertices;
		buffer<triangle_group*> groups;
		buffer<int>            bone_vertex; // What a bone pulls on, and how hard.
		buffer<float>          bone_weight;
		buffer<key3>           pos_keys, scale_keys;
		buffer<key4>           rot_keys;
	};

	struct model {
		buffer<tex_info>   textures;
		buffer<brush_info> brushes;
		buffer<node_info*> nodes; // Parents before children.
		float              frames = 0, fps = 60;
		char*              directory = nullptr;

		~model() {}

		void release()
		{
			for (uint32_t i = 0; i < textures.size; i++) {
				free(textures[i].name);
			}
			for (uint32_t i = 0; i < nodes.size; i++) {
				node_info* n = nodes[i];
				free(n->name);
				n->vertices.release();
				for (uint32_t g = 0; g < n->groups.size; g++) {
					n->groups[g]->indices.release();
					delete n->groups[g];
				}
				n->groups.release();
				n->bone_vertex.release();
				n->bone_weight.release();
				n->pos_keys.release();
				n->scale_keys.release();
				n->rot_keys.release();
				delete n;
			}
			textures.release();
			brushes.release();
			nodes.release();
			free(directory);
		}
	};

	void read_node(reader& r, size_t end, model& m, int parent);

	void read_mesh(reader& r, size_t end, node_info& node)
	{
		node.has_mesh   = true;
		node.mesh_brush = r.read_int();
		while ((r.pos + 8 <= end) && !r.failed) {
			char    tag[5] = { 0, 0, 0, 0, 0 };
			memcpy(tag, r.data + r.pos, 4);
			r.pos += 4;
			int32_t size  = r.read_int();
			size_t  stop  = r.pos + size_t(size);
			if ((size < 0) || (stop > end)) {
				r.failed = true;
				return;
			}
			if (!strcmp(tag, "VRTS")) {
				int flags = r.read_int(), sets = r.read_int(), set_size = r.read_int();
				node.has_normals = (flags & 1) != 0;
				while ((r.pos < stop) && !r.failed) {
					vertex_info v;
					for (int i = 0; i < 3; i++) {
						v.pos[i] = r.read_float();
					}
					if (flags & 1) {
						for (int i = 0; i < 3; i++) {
							v.normal[i] = r.read_float();
						}
					}
					if (flags & 2) {
						for (int i = 0; i < 4; i++) {
							v.color[i] = r.read_float();
						}
					}
					for (int s = 0; s < sets; s++) {
						for (int i = 0; i < set_size; i++) {
							float c = r.read_float();
							if ((s == 0) && (i < 2)) {
								v.uv[i] = c;
							}
						}
					}
					node.vertices.push(v);
				}
			} else if (!strcmp(tag, "TRIS")) {
				triangle_group* group = new triangle_group();
				group->brush          = r.read_int();
				while ((r.pos + 12 <= stop) && !r.failed) {
					for (int i = 0; i < 3; i++) {
						group->indices.push(uint32_t(r.read_int()));
					}
				}
				node.groups.push(group);
			}
			r.pos = stop;
		}
	}

	void read_node(reader& r, size_t end, model& m, int parent)
	{
		node_info* node = new node_info();
		node->parent    = parent;
		node->name      = r.read_string();
		for (int i = 0; i < 3; i++) node->pos[i] = r.read_float();
		for (int i = 0; i < 3; i++) node->scale[i] = r.read_float();
		for (int i = 0; i < 4; i++) node->rot[i] = r.read_float();
		int index = int(m.nodes.size);
		m.nodes.push(node);

		while ((r.pos + 8 <= end) && !r.failed) {
			char tag[5] = { 0, 0, 0, 0, 0 };
			memcpy(tag, r.data + r.pos, 4);
			r.pos += 4;
			int32_t size = r.read_int();
			size_t  stop = r.pos + size_t(size);
			if ((size < 0) || (stop > end)) {
				r.failed = true;
				return;
			}
			if (!strcmp(tag, "MESH")) {
				read_mesh(r, stop, *node);
			} else if (!strcmp(tag, "BONE")) {
				node->is_bone = true;
				while ((r.pos + 8 <= stop) && !r.failed) {
					node->bone_vertex.push(r.read_int());
					node->bone_weight.push(r.read_float());
				}
			} else if (!strcmp(tag, "KEYS")) {
				int flags = r.read_int();
				while ((r.pos + 4 <= stop) && !r.failed) {
					float frame = float(r.read_int());
					if (flags & 1) {
						key3 k = { frame, { r.read_float(), r.read_float(), r.read_float() } };
						node->pos_keys.push(k);
					}
					if (flags & 2) {
						key3 k = { frame, { r.read_float(), r.read_float(), r.read_float() } };
						node->scale_keys.push(k);
					}
					if (flags & 4) {
						key4 k = { frame, { r.read_float(), r.read_float(), r.read_float(), r.read_float() } };
						node->rot_keys.push(k);
					}
				}
			} else if (!strcmp(tag, "ANIM")) {
				r.read_int(); // Flags
				float frames = float(r.read_int());
				float fps    = r.read_float();
				if (index == 0) {
					m.frames = frames;
					m.fps    = fps > 0 ? fps : 60;
				}
			} else if (!strcmp(tag, "NODE")) {
				read_node(r, stop, m, index);
			}
			r.pos = stop;
		}
	}

	bool read_model(const char* path, model& m)
	{
		FILE* file = fopen(path, "rb");
		if (!file) {
			return false;
		}
		fseek(file, 0, SEEK_END);
		long length = ftell(file);
		fseek(file, 0, SEEK_SET);
		uint8_t* data = static_cast<uint8_t*>(malloc(size_t(length) + 1));
		size_t   got  = fread(data, 1, size_t(length), file);
		fclose(file);

		reader r = { data, got, 0, false };
		bool   ok = false;
		if ((got > 12) && !memcmp(data, "BB3D", 4)) {
			r.pos = 4;
			int32_t size = r.read_int();
			size_t  end  = 8 + size_t(size);
			if (end > got) {
				end = got;
			}
			r.read_int(); // Version
			while ((r.pos + 8 <= end) && !r.failed) {
				char tag[5] = { 0, 0, 0, 0, 0 };
				memcpy(tag, r.data + r.pos, 4);
				r.pos += 4;
				int32_t chunk = r.read_int();
				size_t  stop  = r.pos + size_t(chunk);
				if ((chunk < 0) || (stop > end)) {
					r.failed = true;
					break;
				}
				if (!strcmp(tag, "TEXS")) {
					while ((r.pos < stop) && !r.failed) {
						tex_info t;
						t.name  = r.read_string();
						t.flags = r.read_int();
						r.read_int(); // Blend
						for (int i = 0; i < 5; i++) {
							r.read_float(); // Position, scale and rotation, which are not supported.
						}
						m.textures.push(t);
					}
				} else if (!strcmp(tag, "BRUS")) {
					int textures = r.read_int();
					while ((r.pos < stop) && !r.failed) {
						brush_info b;
						free(r.read_string());
						for (int i = 0; i < 4; i++) b.color[i] = r.read_float();
						b.shininess = r.read_float();
						b.blend     = r.read_int();
						b.fx        = r.read_int();
						for (int i = 0; i < textures; i++) {
							int t = r.read_int();
							if (i == 0) {
								b.texture = t;
							}
						}
						m.brushes.push(b);
					}
				} else if (!strcmp(tag, "NODE") && (m.nodes.size == 0)) {
					read_node(r, stop, m, -1);
				}
				r.pos = stop;
			}
			ok = !r.failed && (m.nodes.size > 0);
		}
		free(data);

		// Textures are found next to the model.
		const char* slash = strrchr(path, '/');
		const char* back  = strrchr(path, '\\');
		if (back && (!slash || (back > slash))) {
			slash = back;
		}
		size_t length_dir = slash ? size_t(slash - path) + 1 : 0;
		m.directory       = static_cast<char*>(malloc(length_dir + 1));
		memcpy(m.directory, path, length_dir);
		m.directory[length_dir] = 0;
		return ok;
	}

	bool file_exists(const char* path)
	{
		FILE* f = fopen(path, "rb");
		if (f) {
			fclose(f);
			return true;
		}
		return false;
	}

	// The texture of the model, loaded the first time it is needed. 0 if it could not be found.
	int texture_of_model(model& m, int index)
	{
		if ((index < 0) || (uint32_t(index) >= m.textures.size)) {
			return 0;
		}
		tex_info& t = m.textures[uint32_t(index)];
		if (t.handle >= 0) {
			return t.handle;
		}
		t.handle = 0;
		if (!t.name) {
			return 0;
		}
		// The name may have a path from the machine that made the model, and uses backslashes.
		char* name = static_cast<char*>(malloc(strlen(t.name) + 1));
		strcpy(name, t.name);
		for (char* c = name; *c; c++) {
			if (*c == '\\') {
				*c = '/';
			}
		}
		const char* base = strrchr(name, '/');
		base             = base ? base + 1 : name;
		const char* plain = (name[0] == '.' && name[1] == '/') ? name + 2 : name;

		size_t dir_length = strlen(m.directory);
		char*  path       = static_cast<char*>(malloc(dir_length + strlen(name) + 2));
		const char* candidates[2] = { plain, base };
		for (const char* candidate : candidates) {
			sprintf(path, "%s%s", m.directory, candidate);
			if (file_exists(path)) {
				t.handle = bb_load_texture(path, t.flags ? t.flags : 1);
				break;
			}
			if (file_exists(candidate)) {
				t.handle = bb_load_texture(candidate, t.flags ? t.flags : 1);
				break;
			}
		}
		free(path);
		free(name);
		return t.handle;
	}

	bool material_of(model& m, int brush, material& out)
	{
		if ((brush < 0) || (uint32_t(brush) >= m.brushes.size)) {
			return false;
		}
		brush_info const& b = m.brushes[uint32_t(brush)];
		out.color[0]  = b.color[0];
		out.color[1]  = b.color[1];
		out.color[2]  = b.color[2];
		out.alpha     = b.color[3];
		out.shininess = b.shininess;
		out.texture   = texture_of_model(m, b.texture);
		out.blend     = (b.blend == 3 || b.blend == 2) ? b.blend : 0;
		out.fx        = b.fx;
		return true;
	}

	// Surfaces for the triangle groups of a node, with vertices passed through the matrix (or as they are).
	// If skin is true, what each vertex came from is remembered in order to find out which bones belong to it.
	void build_surfaces(model& m, node_info& node, int entity_handle, const float* matrix, buffer<uint32_t>* sources, buffer<surface*>* made)
	{
		for (uint32_t g = 0; g < node.groups.size; g++) {
			triangle_group& group = *node.groups[g];
			surface*        s     = create_surface(entity_handle);

			// Only the vertices that this group uses.
			buffer<int> remap;
			remap.reserve(node.vertices.size);
			for (uint32_t i = 0; i < node.vertices.size; i++) {
				remap.push(-1);
			}
			buffer<uint32_t> source;
			for (uint32_t i = 0; i < group.indices.size; i++) {
				uint32_t original = group.indices[i];
				if (original >= node.vertices.size) {
					continue;
				}
				if (remap[original] < 0) {
					vertex_info const& v = node.vertices[original];
					vertex3d out         = {};
					if (matrix) {
						float p[3], n[3];
						transform_point(matrix, v.pos, p);
						transform_direction(matrix, v.normal, n);
						out.x = p[0]; out.y = p[1]; out.z = p[2];
						out.nx = n[0]; out.ny = n[1]; out.nz = n[2];
					} else {
						out.x = v.pos[0]; out.y = v.pos[1]; out.z = v.pos[2];
						out.nx = v.normal[0]; out.ny = v.normal[1]; out.nz = v.normal[2];
					}
					out.u = v.uv[0];
					out.v = v.uv[1];
					out.r = uint8_t(v.color[0] * 255 + 0.5f);
					out.g = uint8_t(v.color[1] * 255 + 0.5f);
					out.b = uint8_t(v.color[2] * 255 + 0.5f);
					out.a = uint8_t(v.color[3] * 255 + 0.5f);
					remap[original] = int(s->vertices.size);
					s->vertices.push(out);
					source.push(original);
				}
				s->indices.push(uint32_t(remap[original]));
			}
			s->dirty = true;
			if (!node.has_normals) {
				recalculate_normals(s);
			}

			int       brush = group.brush >= 0 ? group.brush : node.mesh_brush;
			material  paint;
			if (material_of(m, brush, paint)) {
				s->paint   = paint;
				s->painted = true;
			}
			if (sources) {
				sources->push(0); // Marks a new surface.
				for (uint32_t i = 0; i < source.size; i++) {
					sources->push(source[i]);
				}
				sources->push(0xFFFFFFFFu);
			}
			if (made) {
				made->push(s);
			}
			source.release();
			remap.release();
		}
	}

	void set_transform(entity& e, node_info const& n)
	{
		memcpy(e.position, n.pos, sizeof(n.pos));
		memcpy(e.scale, n.scale, sizeof(n.scale));
		float matrix[16], unit[3] = { 1, 1, 1 };
		compose(matrix, n.pos, unit, n.rot);
		euler_from_matrix(matrix, e.rotation);
	}

	// The whole model as entities, with its animation.
	int build_hierarchy(model& m, int parent)
	{
		animation* anim = new animation();
		anim->frames    = m.frames > 0 ? m.frames : 1;
		anim->fps       = m.fps;
		anim->sequences.push({ 0, anim->frames });

		bool has_motion = false;
		buffer<int> handles;
		for (uint32_t i = 0; i < m.nodes.size; i++) {
			node_info& n = *m.nodes[i];
			int        up = n.parent >= 0 ? handles[uint32_t(n.parent)] : parent;
			int        handle = create_entity(n.has_mesh ? MESH : PIVOT, up);
			handles.push(handle);
			set_transform(*get_entity(handle), n);
			if (n.name) {
				bb_name_entity(handle, n.name);
			}

			anim_node* node = new anim_node();
			node->parent    = n.parent;
			node->handle    = handle;
			node->has_mesh  = n.has_mesh;
			node->is_bone   = n.is_bone;
			memcpy(node->pos, n.pos, sizeof(n.pos));
			memcpy(node->scale, n.scale, sizeof(n.scale));
			memcpy(node->rot, n.rot, sizeof(n.rot));
			copy_buffer(node->pos_keys, n.pos_keys);
			copy_buffer(node->scale_keys, n.scale_keys);
			copy_buffer(node->rot_keys, n.rot_keys);
			has_motion = has_motion || n.pos_keys.size || n.scale_keys.size || n.rot_keys.size || n.is_bone;

			// Where the node is in the model when nothing moves.
			float local[16];
			compose(local, n.pos, n.scale, n.rot);
			if (n.parent >= 0) {
				mat_multiply(node->bind_model, anim->nodes[uint32_t(n.parent)]->bind_model, local);
			} else {
				memcpy(node->bind_model, local, sizeof(local));
			}
			mat_affine_inverse(node->bind_model, node->inverse_bind);
			anim->nodes.push(node);
		}

		// Surfaces, and which bones pull on them.
		buffer<surface*> made[1];
		(void)made;
		for (uint32_t i = 0; i < m.nodes.size; i++) {
			node_info& n = *m.nodes[i];
			if (!n.has_mesh) {
				continue;
			}
			buffer<uint32_t> sources;
			buffer<surface*> surfaces;
			build_surfaces(m, n, handles[i], nullptr, &sources, &surfaces);

			// Every bone below this node (or this node) that pulls on its vertices.
			bool skinned = false;
			for (uint32_t b = 0; b < m.nodes.size && !skinned; b++) {
				if (!m.nodes[b]->is_bone) {
					continue;
				}
				for (int up = int(b); up >= 0; up = m.nodes[uint32_t(up)]->parent) {
					if (m.nodes[uint32_t(up)]->has_mesh) {
						skinned = skinned || (up == int(i));
						break;
					}
				}
			}
			if (!skinned) {
				sources.release();
				surfaces.release();
				continue;
			}

			uint32_t cursor = 0;
			for (uint32_t s = 0; s < surfaces.size; s++) {
				cursor++; // The marker
				buffer<uint32_t> ids;
				while (sources[cursor] != 0xFFFFFFFFu) {
					ids.push(sources[cursor++]);
				}
				cursor++;

				surface*   surf = surfaces[s];
				skin_data* skin = new skin_data();
				skin->mesh_node = int(i);
				for (uint32_t v = 0; v < ids.size; v++) {
					vertex_info const& original = n.vertices[ids[v]];
					for (int k = 0; k < 3; k++) {
						skin->bind_position.push(original.pos[k]);
					}
					vertex3d const& built = surf->vertices[v];
					skin->bind_normal.push(built.nx);
					skin->bind_normal.push(built.ny);
					skin->bind_normal.push(built.nz);
				}
				for (uint32_t v = 0; v < ids.size; v++) {
					skin->start.push(skin->bone.size);
					for (uint32_t b = 0; b < m.nodes.size; b++) {
						node_info& bone = *m.nodes[b];
						if (!bone.is_bone) {
							continue;
						}
						// Does this bone belong to this mesh?
						int owner = int(b);
						while ((owner >= 0) && !m.nodes[uint32_t(owner)]->has_mesh) {
							owner = m.nodes[uint32_t(owner)]->parent;
						}
						if (owner != int(i)) {
							continue;
						}
						for (uint32_t w = 0; w < bone.bone_vertex.size; w++) {
							if (uint32_t(bone.bone_vertex[w]) == ids[v]) {
								skin->bone.push(int(b));
								skin->weight.push(bone.bone_weight[w]);
							}
						}
					}
				}
				skin->start.push(skin->bone.size);
				surf->skin = skin;
				ids.release();
			}
			sources.release();
			surfaces.release();
		}

		int root = handles[0];
		if (has_motion) {
			get_entity(root)->anim = anim;
		} else {
			destroy_animation(anim);
		}
		handles.release();
		return root;
	}

	// The whole model as one mesh, as it looks without animation.
	int build_static(model& m, int parent)
	{
		int mesh = create_entity(MESH, parent);
		if (m.nodes[0]->name) {
			bb_name_entity(mesh, m.nodes[0]->name);
		}
		buffer<float*> models;
		for (uint32_t i = 0; i < m.nodes.size; i++) {
			node_info& n     = *m.nodes[i];
			float*     world = static_cast<float*>(malloc(16 * sizeof(float)));
			float      local[16];
			compose(local, n.pos, n.scale, n.rot);
			if (n.parent >= 0) {
				mat_multiply(world, models[uint32_t(n.parent)], local);
			} else {
				memcpy(world, local, sizeof(local));
			}
			models.push(world);
			if (n.has_mesh) {
				build_surfaces(m, n, mesh, world, nullptr, nullptr);
			}
		}
		for (uint32_t i = 0; i < models.size; i++) {
			free(models[i]);
		}
		models.release();
		return mesh;
	}
} // namespace

////////////////////////////////////////////////////////////////////////////////
// Updating animations
////////////////////////////////////////////////////////////////////////////////
static double last_update_time = -1;

static double now_seconds()
{
	struct timespec ts;
	timespec_get(&ts, TIME_UTC);
	return double(ts.tv_sec) + double(ts.tv_nsec) / 1.0e9;
}

extern "C" {
// The frames are counted in time: how many have passed since the last time this was called.
void bb_animation_update(float world_speed)
{
	double now = now_seconds();
	double dt  = (last_update_time < 0) ? 0 : now - last_update_time;
	last_update_time = now;
	dt = dt > 0.1 ? 0.1 : (dt < 0 ? 0 : dt);

	for (int handle = 1; handle <= entity_count(); handle++) {
		entity* e = get_entity(handle);
		if (!e || !e->anim || (e->anim->mode == 0)) {
			continue;
		}
		animation& a        = *e->anim;
		seq_range range    = a.sequences[uint32_t(a.sequence)];
		float      length   = range.last - range.first;
		a.time += a.direction * a.speed * world_speed * float(dt) * a.fps;

		switch (a.mode) {
		case 1: // Loop
			if (length > 1e-6f) {
				if (a.time > range.last) {
					a.time = range.first + fmodf(a.time - range.first, length);
				} else if (a.time < range.first) {
					a.time = range.last - fmodf(range.first - a.time, length);
				}
			}
			break;
		case 2: // Back and forth
			if (a.time > range.last) {
				a.time      = range.last - (a.time - range.last);
				a.direction = -a.direction;
			} else if (a.time < range.first) {
				a.time      = range.first + (range.first - a.time);
				a.direction = -a.direction;
			}
			a.time = a.time < range.first ? range.first : (a.time > range.last ? range.last : a.time);
			break;
		default: // Once
			if ((a.direction * a.speed >= 0) && (a.time >= range.last)) {
				a.time = range.last;
				a.mode = 0;
			} else if ((a.direction * a.speed < 0) && (a.time <= range.first)) {
				a.time = range.first;
				a.mode = 0;
			}
			break;
		}
		apply_pose(a, a.time);
	}
}

int32_t bb_load_anim_mesh(const char* file, int32_t parent)
{
	model m;
	if (!file || !read_model(file, m)) {
		m.release();
		return 0;
	}
	if (parent && !get_entity(parent)) {
		m.release();
		fail("LoadAnimMesh: the parent does not exist.");
	}
	int root = build_hierarchy(m, parent);
	m.release();
	return root;
}

int32_t bb_load_mesh(const char* file, int32_t parent)
{
	model m;
	if (!file || !read_model(file, m)) {
		m.release();
		return 0;
	}
	if (parent && !get_entity(parent)) {
		m.release();
		fail("LoadMesh: the parent does not exist.");
	}
	int mesh = build_static(m, parent);
	m.release();
	return mesh;
}

static animation& need_animation(int32_t handle, const char* what)
{
	if (!get_entity(handle)) {
		char message[96];
		snprintf(message, sizeof(message), "%s: the entity does not exist.", what);
		fail(message);
	}
	animation* a = animation_of(handle);
	if (!a) {
		static animation none;
		if (none.sequences.size == 0) {
			none.sequences.push({ 0, 0 });
			none.mode = 0;
		}
		return none; // Entities that can not be animated just do nothing.
	}
	return *a;
}

// Animate(entity, mode, speed, sequence, transition): 0 stops, 1 loops, 2 goes back and forth, 3 plays once.
void bb_animate(int32_t handle, int32_t mode, float speed, int32_t sequence, float transition)
{
	(void)transition; // The change from one animation to the next is immediate.
	animation& a = need_animation(handle, "Animate");
	if (a.nodes.size == 0) {
		return;
	}
	if ((sequence < 0) || (uint32_t(sequence) >= a.sequences.size)) {
		fail("Animate: that animation sequence does not exist.");
	}
	if ((mode < 0) || (mode > 3)) {
		mode = 1;
	}
	bool restart = (a.sequence != sequence) || (a.mode == 0) || (a.mode != mode);
	a.mode       = mode;
	a.speed      = speed;
	a.sequence   = sequence;
	if (restart && (mode != 0)) {
		seq_range r = a.sequences[uint32_t(sequence)];
		a.direction = 1;
		a.time      = speed >= 0 ? r.first : r.last;
	}
}

int32_t bb_animating(int32_t handle)
{
	animation& a = need_animation(handle, "Animating");
	return (a.nodes.size && (a.mode != 0)) ? 1 : 0;
}

int32_t bb_anim_seq(int32_t handle)
{
	return need_animation(handle, "AnimSeq").sequence;
}

float bb_anim_length(int32_t handle)
{
	animation& a = need_animation(handle, "AnimLength");
	seq_range  r = a.sequences[uint32_t(a.sequence)];
	return r.last - r.first;
}

float bb_anim_time(int32_t handle)
{
	animation& a = need_animation(handle, "AnimTime");
	return a.time - a.sequences[uint32_t(a.sequence)].first;
}

// Shows the model as it is at a time of a sequence, without playing it.
void bb_set_anim_time(int32_t handle, float time, int32_t sequence)
{
	animation& a = need_animation(handle, "SetAnimTime");
	if (a.nodes.size == 0) {
		return;
	}
	if ((sequence < 0) || (uint32_t(sequence) >= a.sequences.size)) {
		fail("SetAnimTime: that animation sequence does not exist.");
	}
	a.sequence = sequence;
	a.time     = a.sequences[uint32_t(sequence)].first + time;
	apply_pose(a, a.time);
}

// Makes a part of the frames a sequence of its own. Returns its number.
int32_t bb_extract_anim_seq(int32_t handle, int32_t first, int32_t last, int32_t source)
{
	animation& a = need_animation(handle, "ExtractAnimSeq");
	if (a.nodes.size == 0) {
		return 0;
	}
	if ((source < 0) || (uint32_t(source) >= a.sequences.size)) {
		fail("ExtractAnimSeq: that animation sequence does not exist.");
	}
	float offset = a.sequences[uint32_t(source)].first;
	a.sequences.push({ offset + float(first), offset + float(last) });
	return int32_t(a.sequences.size) - 1;
}

int32_t bb_add_anim_seq(int32_t handle, int32_t length)
{
	animation& a = need_animation(handle, "AddAnimSeq");
	if (a.nodes.size == 0) {
		return 0;
	}
	a.sequences.push({ a.frames, a.frames + float(length) });
	a.frames += float(length);
	return int32_t(a.sequences.size) - 1;
}
}
